def compute_keystroke_metrics(raw_key_events: list[dict]) -> dict:
    # raw_key_events format: [{'key': 'a', 'down': 1000, 'up': 1090}, ...]
    dwell_times = [event['up'] - event['down'] for event in raw_key_events]
    flight_times = [
        raw_key_events[i+1]['down'] - raw_key_events[i]['up']
        for i in range(len(raw_key_events) - 1)
    ]
    return {
        'mean_dwell_ms': sum(dwell_times) / len(dwell_times) if dwell_times else 0,
        'mean_flight_ms': sum(flight_times) / len(flight_times) if flight_times else 0,
        'dwell_std_dev': (sum((x - (sum(dwell_times)/len(dwell_times)))**2 for x in dwell_times) / len(dwell_times)) ** 0.5 if dwell_times else 0
    }
